//! The largest routines, and everything else that was left.
//!
//! 1223 routines, recorded by what can be counted rather than by shape. Every
//! other table of recovered routines was built by reading a body and writing
//! down its structure; these are the ones where that could not be done — bodies
//! of up to 6805 statements, up to 1719 calls, control flow that jumps, or nothing
//! recovered called at all. Counting is what is left, and counting is honest.
//!
//! The one thing worth saying about the big ones is how they got big. A routine
//! here making fifty calls or more makes about **9.7 calls for every distinct
//! thing it calls** — the same handful of operations, over and over. In the
//! largest table where bodies *were* read, the same measure is under four.
//! These routines are not long because they do many different things; they are
//! long because they repeat a narrow vocabulary, which is what a form being
//! built field by field, or a table filled row by row, looks like once it has
//! been compiled.
//!
//! The largest of all is `0X011AE5B0`: 6805 statements, 417 calls, and 23 distinct
//! things called between them. 502 of these routines call nothing that was
//! recovered, 342 jump, and 479 have a loop.
//!
//! [`Largest::calls`] is a count and [`Largest::distinct`] is a set. Neither is
//! an order: for a body this size, and for one that jumps, the sequence is not
//! something this table claims to know.

// The addresses are written without separators so the port-mapping importer can
// match them against the recovered functions.
#![allow(clippy::unreadable_literal)]

/// One routine recorded by measurement rather than by shape.
#[derive(Debug, Clone, Copy)]
pub struct Largest {
    /// Where it sits.
    pub routine: u32,
    /// Everything it calls, each named once, in address order.
    ///
    /// A set, not a sequence: nothing here says what order they run in.
    pub distinct: &'static [u32],
    /// How many calls it makes in total.
    pub calls: u32,
    /// How many statements its body has.
    pub statements: u32,
    /// How many questions it asks.
    pub questions: u32,
    /// How many loops it has.
    pub loops: u32,
    /// How many jumps it makes.
    pub jumps: u32,
    /// Whether it also calls through a thunk the decompiler could not resolve.
    pub through_a_thunk: bool,
}

