/// How many there are.
pub const LARGEST_COUNT: usize = 1223;

/// Implements part of the largest-routine family.
///
/// What is known of one routine, if it is one of these.
#[must_use]
pub fn routine_at(routine: u32) -> Option<&'static Largest> {
    LARGEST
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &LARGEST[at])
}

/// Implements part of the largest-routine family.
///
/// How many times the average distinct callee is called.
///
/// The measure that says what makes these routines long. A routine calling one
/// thing fifty times and a routine calling fifty things once are the same
/// length and are not the same kind of thing.
#[must_use]
pub fn repeats_per_callee(held: &Largest) -> f64 {
    if held.distinct.is_empty() {
        return 0.0;
    }
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        f64::from(held.calls) / held.distinct.len() as f64
    }
}

/// Implements part of the largest-routine family.
///
/// How much the routines that make many calls repeat themselves.
///
/// Measured over the routines making fifty calls or more, which is where the
/// question means anything.
#[must_use]
pub fn repetition_of_the_busy_ones() -> f64 {
    let busy: Vec<&Largest> = LARGEST
        .iter()
        .filter(|held| held.calls >= 50 && !held.distinct.is_empty())
        .collect();
    if busy.is_empty() {
        return 0.0;
    }
    let total: f64 = busy.iter().map(|held| repeats_per_callee(held)).sum();
    #[expect(
        clippy::cast_precision_loss,
        reason = "a few hundred routines, exact in a double"
    )]
    {
        total / busy.len() as f64
    }
}

/// Implements part of the largest-routine family.
///
/// Whether a routine calls nothing that was recovered.
#[must_use]
pub const fn calls_nothing_recovered(held: &Largest) -> bool {
    held.distinct.is_empty()
}

/// Implements part of the largest-routine family.
///
/// Whether a routine's control flow jumps.
#[must_use]
pub const fn jumps_about(held: &Largest) -> bool {
    held.jumps > 0
}

/// Implements part of the largest-routine family.
///
/// The routine with the most statements in it.
#[must_use]
pub fn the_biggest() -> Option<&'static Largest> {
    LARGEST.iter().max_by_key(|held| held.statements)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(LARGEST.len(), LARGEST_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            LARGEST
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = LARGEST[0].routine;

        assert!(routine_at(known).is_some());
        assert!(routine_at(0).is_none());
    }

    #[test]
    fn every_recorded_call_is_a_function_that_was_recovered() {
        for held in &LARGEST {
            for call in held.distinct {
                assert!(
                    (0x0040_6DE0..=0x01D8_7790).contains(call),
                    "{call:#010X} in {:#010X}",
                    held.routine
                );
            }
        }
    }

    #[test]
    fn the_callees_of_a_routine_are_a_set_and_are_named_once_each() {
        for held in &LARGEST {
            assert!(
                held.distinct.windows(2).all(|pair| pair[0] < pair[1]),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn a_routine_never_has_fewer_calls_than_distinct_callees() {
        for held in &LARGEST {
            assert!(
                held.calls as usize >= held.distinct.len(),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn none_of_these_was_taken_by_a_table_that_reads_bodies() {
        for held in LARGEST.iter().take(300) {
            assert!(crate::nested_routines::routine_at(held.routine).is_none());
            assert!(crate::substantial_routines::routine_at(held.routine).is_none());
            assert!(crate::remaining_routines::routine_at(held.routine).is_none());
            assert!(crate::jumping_routines::routine_at(held.routine).is_none());
        }
    }

    #[test]
    fn the_busy_ones_are_long_because_they_repeat_themselves() {
        // Not because they do many different things. In the largest table where
        // the bodies were actually read, the same measure is under four.
        let here = repetition_of_the_busy_ones();

        assert!(here > 4.0, "{here}");
    }

    #[test]
    fn a_routine_that_calls_one_thing_many_times_repeats_more_than_one_that_does_not() {
        let narrow = Largest {
            routine: 0x0040_7000,
            distinct: &[0x0041_4480],
            calls: 50,
            statements: 100,
            questions: 0,
            loops: 0,
            jumps: 0,
            through_a_thunk: false,
        };
        let wide = Largest {
            distinct: &[
                0x0041_4480,
                0x0041_4560,
                0x0041_44D0,
                0x0041_4520,
                0x0041_B800,
            ],
            ..narrow
        };

        assert!(repeats_per_callee(&narrow) > repeats_per_callee(&wide));
    }

    #[test]
    fn a_routine_calling_nothing_repeats_nothing() {
        let empty = Largest {
            routine: 0x0040_7000,
            distinct: &[],
            calls: 0,
            statements: 10,
            questions: 0,
            loops: 0,
            jumps: 0,
            through_a_thunk: false,
        };

        assert!(calls_nothing_recovered(&empty));
        assert!((repeats_per_callee(&empty) - 0.0).abs() < f64::EPSILON);
    }

    #[test]
    fn some_of_them_call_nothing_that_was_recovered() {
        let quiet = LARGEST
            .iter()
            .filter(|held| calls_nothing_recovered(held))
            .count();

        assert!(quiet > 0);
        assert!(quiet < LARGEST.len());
    }

    #[test]
    fn some_of_them_jump_and_some_of_them_loop() {
        assert!(LARGEST.iter().any(jumps_about));
        assert!(LARGEST.iter().any(|held| held.loops > 0));
    }

    #[test]
    fn the_biggest_routine_is_bigger_than_anything_whose_body_was_read() {
        let here = the_biggest().expect("the table is not empty");
        let there = crate::substantial_routines::SUBSTANTIAL
            .iter()
            .map(|held| held.steps.len())
            .max()
            .expect("some");

        assert!(here.statements as usize > there, "{}", here.statements);
    }

    #[test]
    fn and_it_calls_far_more_times_than_it_calls_different_things() {
        let here = the_biggest().expect("the table is not empty");

        assert!(here.calls as usize > here.distinct.len() * 4);
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = LARGEST.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
